#include <assert.h>
#include <stdio.h>

static void dummy_free(void *value)
{
    (void)value;
}

static void test_create_initial_state(void)
{
    rbtree_t *t = rb_create(NULL);
    assert(t != NULL);
    assert(t->root == NULL);
    assert(t->size == 0);
    assert(t->value_free == NULL);
    free(t);   /* rb_destroy not implemented yet; single allocation so far */
}

static void test_create_stores_value_free(void)
{
    rbtree_t *t = rb_create(dummy_free);
    assert(t != NULL);
    assert(t->value_free == dummy_free);
    free(t);
}

int main(void)
{
    test_create_initial_state();
    test_create_stores_value_free();
    printf("all rb_create tests passed\n");
    return 0;
}

